package com.triathlon.prep.core;

import java.util.*;
import com.triathlon.prep.core.Verification.Mode;
import com.triathlon.prep.core.ReceiptPrintController.*;

public final class ReceiptPrintSelfCheck {
 static int passed;interface Test{void run()throws Exception;}
 static void check(boolean ok,String msg){if(!ok)throw new AssertionError(msg);}
 static void test(String name,Test body)throws Exception{body.run();System.out.println("PASS "+(++passed)+" "+name);}
 static final class Printer implements Transport {
  final Mode mode;int calls,cancels;Reply reply;String job;List<String> lines;boolean thrown;
  Printer(Mode mode){this.mode=mode;}public Mode mode(){return mode;}
  public void print(String job,List<String> lines,Reply reply){if(thrown)throw new IllegalStateException("synthetic printer");this.job=job;this.lines=lines;this.reply=reply;calls++;}
  public void cancel(String job){cancels++;}
 }
 static final CheckInReceipt.Layout LAYOUT=new CheckInReceipt.Layout(384,12,24);
 static void forbidden(ReceiptPrintController p,CheckInReceipt.Document d){try{p.submit(d,LAYOUT);throw new AssertionError("ineligible dispatch allowed");}catch(IllegalStateException expected){}}
 public static void main(String[] args)throws Exception {
  test("roster to TEST verification to marked preview to simulated print acknowledgement",()->{ReceiptSelfCheck.Fixture f=new ReceiptSelfCheck.Fixture(Mode.TEST,RaceRoster.SwimTest.EXPLICIT_BLANK);f.pass();Printer printer=new Printer(Mode.TEST);ReceiptPrintController p=new ReceiptPrintController(f.flow,printer,f.clock,100);CheckInReceipt.Document d=CheckInReceipt.preparePreview(f.flow,f.id);String job=p.submit(d,LAYOUT);check(job.equals(printer.job)&&printer.calls==1&&p.snapshot().status==Status.SENDING,"print not dispatched");check(String.join("",printer.lines).contains("非有效凭条"),"unmarked simulation output");printer.reply.accepted();check(p.snapshot().status==Status.SIMULATED&&p.snapshot().simulation,"simulation called real success");});
  test("simulation slip cannot reach LIVE transport and LIVE slip cannot reach TEST",()->{for(Mode mode:Mode.values()){ReceiptSelfCheck.Fixture f=new ReceiptSelfCheck.Fixture(mode,RaceRoster.SwimTest.UNKNOWN);f.pass();Printer printer=new Printer(mode==Mode.TEST?Mode.LIVE:Mode.TEST);ReceiptPrintController p=new ReceiptPrintController(f.flow,printer,f.clock,100);forbidden(p,mode==Mode.TEST?CheckInReceipt.preparePreview(f.flow,f.id):CheckInReceipt.prepare(f.flow,f.id));check(printer.calls==0,"mode crossed");}});
  test("failed print retries current document using a new job and ignores old callback",()->{ReceiptSelfCheck.Fixture f=new ReceiptSelfCheck.Fixture(Mode.TEST,RaceRoster.SwimTest.MARKED);f.pass();Printer printer=new Printer(Mode.TEST);ReceiptPrintController p=new ReceiptPrintController(f.flow,printer,f.clock,100);CheckInReceipt.Document d=CheckInReceipt.preparePreview(f.flow,f.id);String first=p.submit(d,LAYOUT);Reply old=printer.reply;old.failed(Failure.PRINTER_ERROR);check(p.snapshot().status==Status.FAILED,"failure hidden");String second=p.submit(d,LAYOUT);check(!first.equals(second),"job reused");old.accepted();check(p.snapshot().status==Status.SENDING,"old completion revived");printer.reply.accepted();check(p.snapshot().status==Status.SIMULATED,"retry failed");});
  test("next person invalidates old print callback and blocks stale retry",()->{ReceiptSelfCheck.Fixture f=new ReceiptSelfCheck.Fixture(Mode.TEST,RaceRoster.SwimTest.UNKNOWN);f.pass();Printer printer=new Printer(Mode.TEST);ReceiptPrintController p=new ReceiptPrintController(f.flow,printer,f.clock,100);CheckInReceipt.Document d=CheckInReceipt.preparePreview(f.flow,f.id);p.submit(d,LAYOUT);Reply old=printer.reply;f.flow.next();p.tick();check(p.snapshot().status==Status.CANCELLED&&p.snapshot().failure==Failure.STALE_SESSION,"next left active job");old.accepted();check(p.snapshot().status==Status.CANCELLED,"late callback accepted");forbidden(p,d);check(printer.calls==1,"old person reprinted");});
  test("print timeout and explicit cancel prevent late success",()->{for(boolean timeout:new boolean[]{true,false}){ReceiptSelfCheck.Fixture f=new ReceiptSelfCheck.Fixture(Mode.TEST,RaceRoster.SwimTest.UNKNOWN);f.pass();Printer printer=new Printer(Mode.TEST);ReceiptPrintController p=new ReceiptPrintController(f.flow,printer,f.clock,100);p.submit(CheckInReceipt.preparePreview(f.flow,f.id),LAYOUT);Reply old=printer.reply;if(timeout){f.clock.now=101;p.tick();}else p.cancel();Status finalStatus=timeout?Status.FAILED:Status.CANCELLED;check(p.snapshot().status==finalStatus,"termination missing");old.accepted();check(p.snapshot().status==finalStatus&&printer.cancels>0,"late completion revived");}});
  test("active print cannot duplicate dispatch and thrown driver reports failure",()->{ReceiptSelfCheck.Fixture f=new ReceiptSelfCheck.Fixture(Mode.TEST,RaceRoster.SwimTest.UNKNOWN);f.pass();Printer printer=new Printer(Mode.TEST);ReceiptPrintController p=new ReceiptPrintController(f.flow,printer,f.clock,100);CheckInReceipt.Document d=CheckInReceipt.preparePreview(f.flow,f.id);p.submit(d,LAYOUT);forbidden(p,d);check(printer.calls==1,"duplicate dispatch");p.cancel();printer.thrown=true;p.submit(d,LAYOUT);check(p.snapshot().status==Status.FAILED&&p.snapshot().failure==Failure.PRINTER_ERROR,"exception hidden");});
  test("LIVE acknowledgement is named ACCEPTED without claiming physical printing",()->{ReceiptSelfCheck.Fixture f=new ReceiptSelfCheck.Fixture(Mode.LIVE,RaceRoster.SwimTest.UNKNOWN);f.pass();Printer printer=new Printer(Mode.LIVE);ReceiptPrintController p=new ReceiptPrintController(f.flow,printer,f.clock,100);p.submit(CheckInReceipt.prepare(f.flow,f.id),LAYOUT);printer.reply.accepted();check(p.snapshot().status==Status.ACCEPTED&&!p.snapshot().simulation,"physical proof fabricated");});
  test("closed runtime printer cancels active job and cannot reuse still-passed receipt",()->{ReceiptSelfCheck.Fixture f=new ReceiptSelfCheck.Fixture(Mode.TEST,RaceRoster.SwimTest.UNKNOWN);f.pass();Printer printer=new Printer(Mode.TEST);ReceiptPrintController p=new ReceiptPrintController(f.flow,printer,f.clock,100);CheckInReceipt.Document d=CheckInReceipt.preparePreview(f.flow,f.id);p.submit(d,LAYOUT);Reply old=printer.reply;p.close();check(p.snapshot().status==Status.CANCELLED,"close left active print");old.accepted();forbidden(p,d);check(printer.calls==1,"closed runtime reprinted");});
  System.out.println("SUMMARY "+passed+" printing checks; host-only transports, no physical print or network");
 }
}
